 Beli</small><h5 class="fw-bold mb-0">Rp <?=number_format($grandBuy,0,',','.')?></h5></div></div></div><div class="col-md-4"><div class="card border-0 shadow-sm rounded-4"><div class="card-body"><small class="text-muted">Total Harga Jual</small><h5 class="fw-bold mb-0">Rp <?=number_format($grand,0,',','.')?></h5></div></div></div><div class="col-md-4"><div class="card border-0 shadow-sm rounded-4"><div class="card-body"><small class="text-muted">Total Margin Koperasi</small><h5 class="fw-bold text-success mb-0">Rp <?=number_format($grandMargin,0,',','.')?></h5></div></div></div></div><div class="card border-0 shadow-sm rounded-4"><div class="card-body p-2 p-md-3"><div class="table-responsive"><table class="table align-middle" id="tableLaporanPembelian"><thead><tr><th>Tanggal</th><th>No Pembelian</th><th>SPPG</th><th>Supplier</th><th>Status</th><th>Harga Beli</th><th>Harga Jual</th><th>Margin</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['tanggal_pembelian']))?></td><td><?=esc($r['no_pembelian'])?></td><td><?=esc($names[(string)$r['id_sppg']]??$r['id_sppg'])?></td><td><?=esc($r['supplier']??'-')?></td><td><?=esc(match($r['status']){'draft'=>'Draft','dibeli'=>'Sudah Dibeli','dikirim'=>'Dikirim ke SPPG',default=>$r['status']})?></td><td>Rp <?=number_format((float)($r['total_harga_beli']??0),0,',','.')?></td><td class="fw-bold">Rp <?=number_format($r['grand_total'],0,',','.')?></td><td class="fw-bold <?=((float)($r['total_margin']??0)<0?'text-danger':'text-success')?>">Rp <?=number_format((float)($r['total_margin']??0),0,',','.')?></td><td><a href="<?=base_url('koperasi/pembelian/detail/'.$r['id'])?>" class="btn btn-primary btn-sm">Detail</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?= $this->section('scripts') ?><script>document.addEventListener('DOMContentLoaded',()=>{const t=document.querySelector('#tableLaporanPembelian');if(t)new DataTable(t,{searchable:true,fixedHeight:true,